write: {"content": "import csv

def bubble_sort_by_name(rows):
    arr = rows[:]
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if arr[j][0] > arr[j + 1][0]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

def main():
    with open('компоненты.csv', 'r', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter=';')
        header = next(reader, None)
        rows = [row for row in reader if row]

    sorted_rows = bubble_sort_by_name(rows)

    print(';'.join(header or ['компонент','лицензия','страна правообладателя']))
    for r in sorted_rows:
        print(';'.join(r))

if __name__ == '__main__':
    main()
